/**
 * BreathingPattern contract, v1.
 *
 * Single source of truth: the Zod schema below yields the TypeScript types, the runtime
 * validator (`parsePattern`) and the published JSON Schema
 * (`schema/breathing-pattern.v1.schema.json`, generated by `npm run schema` via `./jsonSchema.ts`).
 *
 * There is no public standard for breathing *patterns*. Health platforms (FHIR, HealthKit
 * mindfulSession, Health Connect MindfulnessSessionRecord) only log sessions. Apps converge on four
 * phases, inhale / holdIn / exhale / holdOut, with 0 meaning skipped. This contract generalises that
 * convention into an ordered list of phases, so patterns such as the physiological sigh
 * (two inhales, one long exhale) or staged Dirga breathing fit too.
 */
import { z } from 'zod';

export const SCHEMA_VERSION = '1';
export const SCHEMA_ID = 'https://raw.githubusercontent.com/felixinberlin/atmende-schildkroete/main/schema/breathing-pattern.v1.schema.json';

export const PhaseKindSchema = z
  .enum(['inhale', 'hold', 'exhale'])
  .describe('Breath direction. A hold keeps the lung volume reached by the previous phase.');

export const EasingSchema = z
  .enum(['linear', 'easeInOutCubic', 'easeOutSine'])
  .describe('Curve of the volume change within the phase. Ignored for holds.');

const Duration = z.number().int().nonnegative().max(120_000).describe('Duration in milliseconds at speed 1.');

/**
 * Breathing regions, using the standard three-part terminology of respiratory physiology and breathing practice:
 * abdominal (diaphragmatic, belly), thoracic (costal, ribs/flanks), clavicular (upper chest, collarbones).
 * A full "three-part breath" fills them in that order. Renderers map each region to their own figure.
 */
export const BreathingRegionSchema = z
  .enum(['abdominal', 'thoracic', 'clavicular'])
  .describe('Standard breathing region: abdominal (diaphragmatic/belly), thoracic (costal/ribs), clavicular (upper chest).');

export const BREATHING_REGIONS = BreathingRegionSchema.options;

export const SegmentSchema = z
  .object({
    durationMs: Duration.positive(),
    region: BreathingRegionSchema,
    label: z.string().optional()
  })
  .describe('Sub-stage of a phase (e.g. the three-part breath). Durations are relative weights over the phase.');

export const ExhaleStyleSchema = z
  .enum(['passive', 'gentle'])
  .describe('Exhale cue style: "passive" (natural elastic recoil) or "gentle" (gentle abdominal engagement). Default is gentle.');

export const GuideArmsSchema = z
  .enum(['hands-on-body', 'raise-on-inhale'])
  .describe('Arm cue variant: "hands-on-body" (default, hands on belly and chest) or "raise-on-inhale" (arms rotate up overhead on inhale).');

export const GuideOptionsSchema = z
  .object({
    arms: GuideArmsSchema.optional()
  })
  .describe('Optional visual cues for the human guide figure.');

export const PhaseSchema = z
  .object({
    kind: PhaseKindSchema,
    durationMs: Duration.describe('Duration in ms at speed 1. 0 means the phase is skipped.'),
    targetVolume: z
      .number()
      .min(0)
      .max(1)
      .optional()
      .describe('Lung fill at the end of the phase (0 = empty, 1 = full). Defaults: inhale 1, exhale 0. Not allowed on holds.'),
    easing: EasingSchema.optional(),
    label: z.string().optional().describe('Display label, e.g. "Ruhe".'),
    cue: z.string().optional().describe('Audio/visual cue key; renderers pick a default per kind when omitted.'),
    airway: z.enum(['nose', 'mouth']).optional(),
    segments: z.array(SegmentSchema).min(1).optional()
  })
  .refine(p => !(p.kind === 'hold' && p.targetVolume !== undefined), {
    message: 'A hold keeps the current volume; targetVolume is not allowed.',
    path: ['targetVolume']
  });

export const BreathingPatternSchema = z
  .object({
    $schema: z.string().optional(),
    schemaVersion: z.literal(SCHEMA_VERSION),
    id: z.string().regex(/^[a-z0-9][a-z0-9-]*$/, 'lowercase slug'),
    name: z.string().min(1),
    shortName: z.string().optional(),
    description: z.string().optional(),
    locale: z.string().optional().describe('BCP 47 language tag of the texts, e.g. "de-DE".'),
    tags: z.array(z.string()).optional(),
    safety: z
      .object({
        notes: z.string().optional(),
        contraindications: z.array(z.string()).optional()
      })
      .optional(),
    exhaleStyle: ExhaleStyleSchema.optional(),
    guide: GuideOptionsSchema.optional(),
    phases: z.array(PhaseSchema).min(1)
  })
  .refine(p => p.phases.some(ph => ph.durationMs > 0 && ph.kind !== 'hold'), {
    message: 'A pattern needs at least one inhale or exhale with a positive duration.',
    path: ['phases']
  })
  .meta({ id: 'BreathingPattern', title: 'Breathing pattern', description: 'A looping breathing exercise.' });

export type PhaseKind = z.infer<typeof PhaseKindSchema>;
export type Easing = z.infer<typeof EasingSchema>;
export type Segment = z.infer<typeof SegmentSchema>;
export type BreathingRegion = z.infer<typeof BreathingRegionSchema>;
export type ExhaleStyle = z.infer<typeof ExhaleStyleSchema>;
export type GuideArms = z.infer<typeof GuideArmsSchema>;
export type GuideOptions = z.infer<typeof GuideOptionsSchema>;
export type BreathPhase = z.infer<typeof PhaseSchema>;
export type BreathingPattern = z.infer<typeof BreathingPatternSchema>;

/** Validate untrusted input (JSON from files, CMS, network). Throws a readable error. */
export function parsePattern(input: unknown): BreathingPattern {
  const result = BreathingPatternSchema.safeParse(input);
  if (!result.success) {
    throw new Error(`Ungültiges Atemmuster: ${z.prettifyError(result.error)}`);
  }
  return result.data;
}

/** Whether a pattern contains any breath hold (useful for safety filtering). */
export function isHoldFree(pattern: BreathingPattern): boolean {
  return !pattern.phases.some(p => p.kind === 'hold' && p.durationMs > 0);
}

export interface FourPhaseTimings {
  inhale: number;
  holdIn: number;
  exhale: number;
  holdOut: number;
}

export const MIN_BREATH_MS = 1000;
export const MAX_PHASE_MS = 20_000;

const clampMs = (value: number, min: number) =>
  Number.isFinite(value) ? Math.min(MAX_PHASE_MS, Math.max(min, Math.round(value))) : min;

/** Build a pattern from the common inhale/holdIn/exhale/holdOut convention (ms). Inputs are clamped. */
export function fromFourPhase(
  timings: FourPhaseTimings,
  meta: Pick<BreathingPattern, 'id' | 'name'> & Partial<BreathingPattern> = { id: 'custom', name: 'Individueller Atemrhythmus' }
): BreathingPattern {
  return parsePattern({
    schemaVersion: SCHEMA_VERSION,
    ...meta,
    phases: [
      { kind: 'inhale', durationMs: clampMs(timings.inhale, MIN_BREATH_MS) },
      { kind: 'hold', durationMs: clampMs(timings.holdIn, 0) },
      { kind: 'exhale', durationMs: clampMs(timings.exhale, MIN_BREATH_MS) },
      { kind: 'hold', durationMs: clampMs(timings.holdOut, 0), label: 'Ruhe' }
    ]
  });
}
